        },
        {
          "id": "memory_join",
          "name": "Associação em memória com complexidade O(N)",
          "description": "Constrói um dicionário/mapa de customer_id para customer e usa esse mapa para atribuir o cliente a cada fatura em O(N), sem loops aninhados (find/filter dentro de map/for) que gerariam O(N²).",
          "weight": 0.25
        },
        {
          "id": "contract_preservation",
          "name": "Preservação do contrato de saída",
          "description": "A função retorna exatamente o mesmo formato que o código original — lista de faturas com a propriedade customer preenchida — sem alterar a assinatura pública nem omitir campos.",
          "weight": 0.15
        }
      ]
    }
  },
  "answer": {
    "kind": "student",
    "resposta": "",
    "raciocinio": "1. Causa raiz do N+1:
O código original executa db.query dentro do loop for...of: para cada uma das
N faturas, dispara uma query individual ao banco (SELECT WHERE id = ?). Somada
à query inicial de faturas, o total é N+1 idas ao banco. Para 100 faturas,
são 101 queries. O problema é agravado por IDs repetidos: o mesmo cliente pode
ser buscado múltiplas vezes, desperdiçando I/O adicional.

2. Extração de IDs únicos e query em lote:
Usei new Set(invoices.map(i => i.customer_id)) para coletar apenas os
customer_ids distintos, eliminando duplicatas. Em seguida, montei dinamicamente
a lista de placeholders (?) e executei uma única query com IN, reduzindo o
total de queries para 2 independentemente do volume de faturas.

3. Mapa para associação em memória:
Construí um Map com new Map(customers.map(c => [c.id, c])): para cada cliente
retornado, a chave é o id e o valor é o objeto completo. Isso permite buscar o
cliente de qualquer fatura com customerMap.get(invoice.customer_id) em tempo O(1).

4. Por que O(N) e não O(N²):
Com o Map, o loop de associação executa um get por fatura — operação O(1)
amortizada. O total do passo de associação é O(N). Sem o Map, usar
customers.find(c => c.id === invoice.customer_id) dentro do loop seria O(N)
por fatura, resultando em O(N²) no total. Para N=100, a diferença é 100 vs
10.000 operações no pior caso.
",
    "codigo": "// invoice-service.js

const db = {
  query: async (sql, params = []) => {
    console.log('DB QUERY:', sql, params);
    return [];
  },
};

async function getInvoicesWithCustomers() {
  // Query 1: busca as faturas
  const invoices = await db.query(
    'SELECT * FROM invoices ORDER BY date DESC LIMIT 100'
  );

  if (invoices.length === 0) {
    return [];
  }

  // Extrai customer_ids únicos para evitar queries redundantes
  const uniqueIds = [...new Set(invoices.map(i => i.customer_id))];

  // Query 2: busca todos os clientes relevantes em lote com IN
  const placeholders = uniqueIds.map(() => '?').join(', ');
  const customers = await db.query(
    `SELECT * FROM customers WHERE id IN (${placeholders})`,
    uniqueIds
  );

  // Constrói mapa customer_id → customer para acesso O(1)
  const customerMap = new Map(customers.map(c => [c.id, c]));

  // Associa cliente a cada fatura em O(N)
  for (const invoice of invoices) {
    invoice.customer = customerMap.get(invoice.customer_id) ?? null;
  }

  return invoices;
}

module.exports = { getInvoicesWithCustomers };
